static int test_annex_j10_hnp(void)
{
    struct sae_data sae = { 0 };
    struct wpabuf *buf = NULL;
    struct crypto_bignum *mask = NULL;
    const u8 addr1[ETH_ALEN] = { 0x4d, 0x3f, 0x2f, 0xff, 0xe3, 0x87 };
    const u8 addr2[ETH_ALEN] = { 0xa5, 0xd8, 0xaa, 0x95, 0x8e, 0x3c };
    const u8 password[] = "mekmitasdigoat";
    int ret = -1;

    buf = wpabuf_alloc(128);
    if (!buf || sae_set_group(&sae, 19) < 0 ||
        sae_prepare_commit(addr1, addr2, password, sizeof(password) - 1,
                           &sae) < 0)
        goto done;

    crypto_bignum_deinit(sae.tmp->sae_rand, 1);
    sae.tmp->sae_rand = crypto_bignum_init_set(local_rand, sizeof(local_rand));
    mask = crypto_bignum_init_set(local_mask, sizeof(local_mask));
    if (!sae.tmp->sae_rand || !mask ||
        crypto_bignum_add(sae.tmp->sae_rand, mask,
                          sae.tmp->own_commit_scalar) < 0 ||
        crypto_bignum_mod(sae.tmp->own_commit_scalar, sae.tmp->order,
                          sae.tmp->own_commit_scalar) < 0 ||
        crypto_ec_point_mul(sae.tmp->ec, sae.tmp->pwe_ecc, mask,
                            sae.tmp->own_commit_element_ecc) < 0 ||
        crypto_ec_point_invert(sae.tmp->ec,
                               sae.tmp->own_commit_element_ecc) < 0)
        goto done;

    if (sae_write_commit(&sae, buf, NULL, NULL, 0) < 0 ||
        wpabuf_len(buf) != sizeof(local_commit) ||
        memcmp(wpabuf_head(buf), local_commit, sizeof(local_commit)) != 0)
        goto done;
    if (sae_parse_commit(&sae, peer_commit, sizeof(peer_commit), NULL, NULL,
                         NULL, 0, NULL) != WLAN_STATUS_SUCCESS)
        goto done;
    if (sae_process_commit(&sae) < 0)
        goto done;
    if (memcmp(sae.tmp->kck, kck, sizeof(kck)) != 0)
        goto done;
    if (memcmp(sae.pmk, pmk, sizeof(pmk)) != 0) {
        goto done;
    }
    if (memcmp(sae.pmkid, pmkid, sizeof(pmkid)) != 0)
        goto done;
    ret = 0;
done:
    sae_clear_data(&sae);
    wpabuf_free(buf);
    crypto_bignum_deinit(mask, 1);
    return ret;
}

static int test_annex_j10_h2e_pwe(void)
{
    const u8 addr1[ETH_ALEN] = { 0x00, 0x09, 0x5b, 0x66, 0xec, 0x1e };
    const u8 addr2[ETH_ALEN] = { 0x00, 0x0b, 0x6b, 0xd9, 0x02, 0x46 };
    const u8 ssid[] = "byteme";
    const u8 password[] = "mekmitasdigoat";
    const u8 password_id[] = "psk4internet";
    int groups[] = { 19, 0 };
    struct sae_pt *pt = NULL;
    struct crypto_ec_point *pwe = NULL;
    u8 coordinates[64];
    int ret = -1;

    pt = sae_derive_pt(groups, ssid, sizeof(ssid) - 1,
                       password, sizeof(password) - 1,
                       password_id, sizeof(password_id) - 1);
    if (!pt || pt->group != 19 || !pt->ec)
        goto done;
    pwe = sae_derive_pwe_from_pt_ecc(pt, addr1, addr2);
    if (!pwe || crypto_ec_point_to_bin(pt->ec, pwe, coordinates,
                                       coordinates + 32) < 0 ||
        memcmp(coordinates, pwe_19_x, sizeof(pwe_19_x)) != 0 ||
        memcmp(coordinates + 32, pwe_19_y, sizeof(pwe_19_y)) != 0)
        goto done;
    ret = 0;
done:
    forced_memzero(coordinates, sizeof(coordinates));
    crypto_ec_point_deinit(pwe, 1);
    sae_deinit_pt(pt);
    return ret;
}

int main(void)
{
    if (test_annex_j10_hnp() < 0) {
        fputs("Hostap Annex J.10 H&P commit/KCK/PMK/PMKID vector failed\n", stderr);
        return 1;
    }
    if (test_annex_j10_h2e_pwe() < 0) {
        fputs("Hostap Annex J.10 H2E PT/PWE vector failed\n", stderr);
        return 1;
    }
    puts("Hostap Annex J.10 group 19 H&P/H2E vectors passed");
    return 0;
}
